package dashboard

import (
	"encoding/json"
	"errors"
	"fmt"
	"html"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/statechart"
	"github.com/gitdek/invariant/internal/tla"
	"github.com/gitdek/invariant/internal/tlc"
	"github.com/gitdek/invariant/internal/verify"
)

// A size-limited reader keeps independent counterexamples in the optional
// Limitation.bug_paths field, with the same records as Report.bug_paths.
// Compute still returns no partial correct-model chart on too_large. Its
// Refusal.Limitation retains the paths; Read carries that limitation through
// proposals and receipts. Limitations without paths keep their original bytes.
// Trace-state mapping is independent of whole-chart eligibility: use a matching
// reader label, or "TLC state N" when there is no matching state rule. Lookup
// errors are diagnostics, not missing labels. No step is collapsed or hidden.
func dashboard669Limited(t *testing.T) reader631Fixture {
	t.Helper()
	const n = 501
	f := reader631FixtureFor(t, n, "unused")
	model := strings.Replace(reader631Model, "====", "BadA == n = 1 /\\ n' = Limit + 1\n====", 1)
	f.Files[f.Manifest.Module] = []byte(model)
	f.Lock.Statements = append(f.Lock.Statements, project.Statement{
		Name: "BadA", Kind: project.Bug, Expect: "Safe", Says: "Cross the bound after starting.", CodeBehavior: "hypothetical",
	})
	for i := range f.Lock.Statements {
		s := &f.Lock.Statements[i]
		var err error
		s.SHA256, err = tla.PinHashWith(model, map[string]string{"Helper631.tla": string(f.Files[".invariant/specs/Helper631.tla"])}, s.Name, project.Model)
		if err != nil {
			t.Fatal(err)
		}
	}
	var view strings.Builder
	view.WriteString(`{"version":1,"state":[`)
	for i := 0; i < n; i++ {
		if i > 0 {
			view.WriteByte(',')
		}
		fmt.Fprintf(&view, `{"id":"s%d","when":{"eq":[{"var":"n"},"%d"]},"label":"Stage %d"}`, i, i, i)
	}
	// No catch-all: the violating state is outside the correct graph and has
	// no reader label. The path must still include its third TLC state.
	view.WriteString(`],"step":[{"id":"all","when":true,"label":"Continue"}]}`)
	f.Files[".invariant/view.json"] = []byte(view.String())
	g := tlc.GraphResult{Module: "Dashboard631", Config: tlc.Config{Specification: "Spec", Constants: f.Lock.Bounds, Invariants: []string{"Safe"}},
		Tool:       tlc.GraphTool{Image: f.Report.Toolchain.JavaImage, JarSHA256: f.Report.Toolchain.TLCJarSHA256},
		Run:        tlc.Result{Outcome: tlc.Passed, Version: f.Report.Toolchain.TLC, Depth: n, DistinctStates: n, StatesGenerated: 2*n + 1},
		StateCount: n, StepCount: 2 * n, Graph: tlc.Graph{Initial: []string{"0"}}}
	truth := map[string]map[string]bool{}
	for i := 0; i < n; i++ {
		id, to, action := strconv.Itoa(i), strconv.Itoa((i+1)%n), "Advance"
		if i == n-1 {
			action = "Reset"
		}
		g.Graph.States = append(g.Graph.States, tlc.GraphState{ID: id, Label: "n = " + id, Values: map[string]string{"n": id}})
		g.Graph.Steps = append(g.Graph.Steps, tlc.GraphStep{From: id, To: to, Action: action}, tlc.GraphStep{From: id, To: id, Action: "Poll"})
		truth[id] = map[string]bool{"Safe": true}
	}
	trace := tlc.TraceFile{Module: g.Module, Check: "known bug bad-a", Violated: "Safe", TLC: g.Run.Version,
		States: []tlc.TraceState{
			{Index: 1, Action: "Initial predicate", TLA: map[string]string{"n": "0"}},
			{Index: 2, Action: "Advance", TLA: map[string]string{"n": "1"}},
			{Index: 3, Action: "BadA", TLA: map[string]string{"n": "501"}},
		}}
	check := map[string]any{"name": "BadA", "label": "bad-a", "caught": true, "outcome": "violated", "violated": "Safe", "trace": trace,
		"source":     statechart.Source{Module: g.Module, Config: tlc.Config{Specification: "Invariant_BuggySpec", Constants: f.Lock.Bounds, Invariants: []string{"Safe"}}, Tool: g.Tool, TLC: g.Run.Version},
		"snapshot":   map[string]any{"model_sha256": reader631Hash(f.Files[f.Manifest.Module]), "view_sha256": reader631Hash(f.Files[".invariant/view.json"]), "includes": map[string]string{"Helper631.tla": reader631Hash(f.Files[".invariant/specs/Helper631.tla"])}},
		"invariants": []map[string]bool{{"Safe": true}, {"Safe": true}, {"Safe": false}}, "planted": []int{3}}
	in := statechart.Input{Graph: g, Lock: f.Lock, Invariants: truth}
	var raw map[string]any
	if err := json.Unmarshal(reader631JSON(t, in), &raw); err != nil {
		t.Fatal(err)
	}
	raw["bugs"] = []any{check}
	if err := json.Unmarshal(reader631JSON(t, raw), &in); err != nil {
		t.Fatal(err)
	}
	c, err := statechart.Compute(t.Context(), in, f.Files[".invariant/view.json"])
	var refusal *statechart.Refusal
	if c != nil || !errors.As(err, &refusal) || refusal.Code != "too_large" || refusal.Limitation == nil {
		t.Fatalf("501 projected states must remain a chart limitation: %v", err)
	}
	l := refusal.Limitation
	if l.Kind != "projected_states" || l.Actual != n || l.Limit != 500 || l.ViewChecked == nil || !*l.ViewChecked || l.Validate() != nil {
		t.Fatalf("main chart limitation changed: %+v", l)
	}
	var saved struct {
		Paths []struct {
			Name, Status string
			Trace        tlc.TraceFile
			States       []struct {
				Index int
				Label string
			}
		} `json:"bug_paths"`
	}
	if err = json.Unmarshal(reader631JSON(t, l), &saved); err != nil {
		t.Fatal(err)
	}
	if len(saved.Paths) != 1 || saved.Paths[0].Name != "BadA" || saved.Paths[0].Status != "path" {
		t.Fatal("size limitation discarded the independently drawable known-bug path")
	}
	p := saved.Paths[0]
	if len(p.States) != 3 || !reflect.DeepEqual(p.Trace, trace) {
		t.Fatal("chart limit changed the original TLC sequence")
	}
	for i, want := range []string{"Stage 0", "Stage 1", "TLC state 3"} {
		if p.States[i].Index != i+1 || p.States[i].Label != want {
			t.Fatalf("lost reader label or TLC fallback at step %d: %+v", i+1, p.States[i])
		}
	}
	f.Report.Reader.Chart, f.Report.Reader.Limitation = nil, l
	bug := map[string]any{"name": "BadA", "label": "bad-a", "says": f.Lock.Statements[2].Says, "expect": "Safe", "caught": true, "outcome": "violated", "violated": "Safe", "steps": 2, "counterexample": trace, "code_behavior": "hypothetical"}
	if err = json.Unmarshal(reader631JSON(t, []any{bug}), &f.Report.Bugs); err != nil {
		t.Fatal(err)
	}
	f.bind(t)
	return f
}

func TestKnownBug669PathWithoutDrawableChart(t *testing.T) {
	f := dashboard669Limited(t)
	archive := t.TempDir()
	if err := receipt.Write(archive, f.Report); err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{"receipt.json", "reader.json", "reader.svg", "receipt.md"} {
		b, err := os.ReadFile(filepath.Join(archive, name))
		if err != nil {
			t.Fatal(err)
		}
		text := html.UnescapeString(string(b))
		for _, want := range []string{"BadA", "Stage 0", "Stage 1", "TLC state 3", "Cross the bound after starting.", "Limit", "Helper631.tla"} {
			if !strings.Contains(text, want) {
				t.Fatalf("%s lost standalone path evidence %q", name, want)
			}
		}
		if name == "reader.svg" && (strings.Count(text, `data-bug-path=`) != 1 || strings.Count(text, `data-trace-index=`) != 3) {
			t.Fatal("limited reader must draw one separate, complete numbered SVG path")
		}
		if name == "receipt.md" && strings.Count(text, "```mermaid") != 1 {
			t.Fatal("limited receipt must draw only its known-bug Mermaid path")
		}
	}
	data, err := os.ReadFile(filepath.Join(archive, "receipt.json"))
	if err != nil {
		t.Fatal(err)
	}
	var restored verify.Report
	if err = json.Unmarshal(data, &restored); err != nil || !reflect.DeepEqual(reader631JSON(t, restored.Reader), reader631JSON(t, f.Report.Reader)) {
		t.Fatal("archive changed the limitation or independent path", err)
	}
	r := reader631Repo(t, "owner/large-bugs", strings.Repeat("7", 40), 669, []reader631Fixture{f}, reader631Archive(t, []reader631Fixture{f}, nil))
	s := &Server{Repos: []*Repo{r}, Cache: t.TempDir()}
	p := reader631Find(t, reader631Load(t, s, r), r.Name, f.Dir)
	if p.Status != "too_large" || p.SVG == "" {
		t.Fatalf("retain the chart limitation and expose the independent path image: %+v", p)
	}
	visible := func(server *Server) (string, string) {
		page, svg := reader631GET(server, "GET", p.Page, ""), reader631GET(server, "GET", p.SVG, "")
		if page.Code != 200 || svg.Code != 200 {
			t.Fatalf("standalone path endpoints: %d, %d", page.Code, svg.Code)
		}
		body := html.UnescapeString(page.Body.String())
		if !strings.Contains(body, `data-bug-path="BadA"`) || !strings.Contains(body, "TLC state 3") || !strings.Contains(body, "501") || !strings.Contains(body, "500") {
			t.Fatal("dashboard hid the path or the chart's independent size diagnostic")
		}
		if strings.Contains(strings.ToLower(body+svg.Body.String()), "<script") {
			t.Fatal("standalone path requires script")
		}
		return page.Body.String(), svg.Body.String()
	}
	page, svg := visible(s)
	cold := &Server{Cache: s.Cache, Repos: []*Repo{{Name: r.Name}}}
	cold.loadSnapshot()
	page2, svg2 := visible(cold)
	if page != page2 || svg != svg2 {
		t.Fatal("offline recovery lost the independent path on a limited model")
	}
}

