package statechart_test

import (
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"html"
	"reflect"
	"strconv"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/statechart"
	"github.com/gitdek/invariant/internal/tlc"
)

// #669's additive wire contract. Input.Bugs (json:"bugs") is checker-owned,
// never accepted from view.json. Each entry holds name, label, caught, outcome,
// violated, message, trace (*tlc.TraceFile), source (statechart.Source), snapshot
// ({model_sha256,view_sha256,includes}), invariants (one complete locked-invariant
// row per trace state), and planted (one-based arrival indices established by
// TLC's evaluation of the planted action on those concrete transitions).
// A temporal closing edge may additionally have loop_planted. Read must obtain
// this evidence from the existing bug check and the captured model, not infer
// actions or invariant truth from display labels or the correct-model graph.
//
// Result.Report.bug_paths retains each check's name, label, says, expect,
// rule_says, caught, outcome, violated, message, source, snapshot and exact trace.
// A drawable entry has status:"path", kind:"safety"|"temporal", shortest:true
// only for a TLC breadth-first invariant counterexample, and states in original
// order: {index,id,label,action,action_says,planted,violated_rules}. ID partitions
// by (reader label, false invariant set), but occurrences are NEVER collapsed.
// A failed/uncaught/missing or invalid trace has status:"diagnostic", a specific
// nonempty diagnostic code and message, no drawn states and no shortest claim.
// These fields are optional when absent on historical records, preserving all
// existing no-path JSON, Markdown and SVG bytes and verification fingerprints.
//
// Every successful SVG path is a separate g[data-bug-path="<name>"], containing
// g[data-trace-index="N"] nodes, readable numbered labels and directed paths.
// These are accessibility/inspection hooks, not a layout or color prescription.
// Markdown and CompactMarkdown each show a separate complete numbered Mermaid
// path per successful check, exact says words, bounds/source and true endings.

func bug669JSON(t *testing.T, v any) []byte {
	t.Helper()
	b, e := json.Marshal(v)
	if e != nil {
		t.Fatal(e)
	}
	return b
}
func bug669Map(t *testing.T, v any) map[string]any {
	t.Helper()
	var m map[string]any
	if e := json.Unmarshal(bug669JSON(t, v), &m); e != nil {
		t.Fatal(e)
	}
	return m
}
func bug669Inputs(t *testing.T) (statechart.Input, string, []map[string]any) {
	t.Helper()
	in := reader586Input()
	in.Graph.Config.Invariants = []string{"Safe", "Owned"}
	in.Lock.Statements = append(in.Lock.Statements,
		project.Statement{Name: "Owned", Kind: project.Invariant, Says: "Every result has its owner.", SHA256: strings.Repeat("e", 64)},
		project.Statement{Name: "EventuallyDone", Kind: project.Property, Says: "Every job eventually finishes.", SHA256: strings.Repeat("f", 64)})
	for id := range in.Invariants {
		in.Invariants[id]["Owned"] = true
	}
	for _, s := range []project.Statement{
		{Name: "BadA", Kind: project.Bug, Says: "Lose <a result> & keep going.", Expect: "Safe"},
		{Name: "BadB", Kind: project.Bug, Says: "Lose the owner too.", Expect: "Owned"},
		{Name: "Spin", Kind: project.Bug, Says: "Keep working forever.", Expect: "EventuallyDone"},
		{Name: "Stall", Kind: project.Bug, Says: "Stop making progress.", Expect: "EventuallyDone"},
		{Name: "Miss", Kind: project.Bug, Says: "A bug that was not caught.", Expect: "Safe"},
		{Name: "Failed", Kind: project.Bug, Says: "A check that failed.", Expect: "Safe"},
		{Name: "WrongRule", Kind: project.Bug, Says: "Break a different rule than expected.", Expect: "Owned"},
		{Name: "Absent", Kind: project.Bug, Says: "A check with no counterexample.", Expect: "Safe"},
	} {
		s.SHA256 = strings.Repeat("a", 64)
		in.Lock.Statements = append(in.Lock.Statements, s)
	}
	// n=worker distinguishes the two consecutive Working occurrences; the last
	// value 9 is absent from the correct graph. A collapsed chart has a shortcut
	// Ready -> Working, but cannot supply or shorten this concrete behavior.
	trace := tlc.TraceFile{Module: "Lifecycle", Check: "known bug bad-a", Violated: "Safe", TLC: in.Graph.Run.Version, States: []tlc.TraceState{
		{Index: 1, Action: "Initial predicate", TLA: map[string]string{"phase": `"idle"`, "worker": "0"}},
		{Index: 2, Action: "Start", TLA: map[string]string{"phase": `"busy"`, "worker": "0"}},
		{Index: 3, Action: "Poll", TLA: map[string]string{"phase": `"busy"`, "worker": "1"}},
		{Index: 4, Action: "BadA", TLA: map[string]string{"phase": `"busy"`, "worker": "9"}},
	}}
	source := statechart.Source{Module: in.Graph.Module, Config: tlc.Config{Specification: "Invariant_BuggySpec", Constants: in.Lock.Bounds, Invariants: []string{"Safe", "Owned"}}, Tool: in.Graph.Tool, TLC: in.Graph.Run.Version}
	snapshot := map[string]any{"model_sha256": "sha256:" + strings.Repeat("1", 64), "view_sha256": fmt.Sprintf("sha256:%x", sha256.Sum256([]byte(reader586View))), "includes": map[string]string{"Local.tla": "sha256:" + strings.Repeat("3", 64)}}
	first := map[string]any{"name": "BadA", "label": "bad-a", "caught": true, "outcome": "violated", "violated": "Safe", "trace": trace, "source": source, "snapshot": snapshot, "invariants": []map[string]bool{{"Safe": true, "Owned": true}, {"Safe": true, "Owned": true}, {"Safe": true, "Owned": true}, {"Safe": false, "Owned": true}}, "planted": []int{4}}
	second := bug669Map(t, first)
	second["name"] = "BadB"
	second["label"] = "bad-b"
	second["violated"] = "Owned"
	tr := bug669Map(t, trace)
	tr["check"] = "known bug bad-b"
	tr["violated"] = "Owned"
	tr["states"].([]any)[3].(map[string]any)["action"] = "BadB"
	second["trace"] = tr
	second["invariants"] = []map[string]bool{{"Safe": true, "Owned": true}, {"Safe": true, "Owned": true}, {"Safe": true, "Owned": true}, {"Safe": true, "Owned": false}}
	return in, reader586View, []map[string]any{first, second}
}
func bug669Compute(t *testing.T, in statechart.Input, view string, bugs []map[string]any) *statechart.Result {
	t.Helper()
	raw := bug669Map(t, in)
	raw["bugs"] = bugs
	if e := json.Unmarshal(bug669JSON(t, raw), &in); e != nil {
		t.Fatal(e)
	}
	out, e := statechart.Compute(t.Context(), in, []byte(view))
	if e != nil || out == nil {
		t.Fatalf("compute bug paths: %v", e)
	}
	return out
}
func bug669Paths(t *testing.T, c *statechart.Result) []map[string]any {
	t.Helper()
	var out struct {
		Report struct {
			Paths []map[string]any `json:"bug_paths"`
		} `json:"report"`
	}
	if e := json.Unmarshal(bug669JSON(t, c), &out); e != nil {
		t.Fatal(e)
	}
	if len(out.Report.Paths) == 0 {
		t.Fatal("reader report discarded the known-bug counterexamples")
	}
	return out.Report.Paths
}
func bug669Named(t *testing.T, paths []map[string]any, name string) map[string]any {
	t.Helper()
	for _, p := range paths {
		if p["name"] == name {
			return p
		}
	}
	t.Fatalf("missing bug %s", name)
	return nil
}
func TestKnownBug669ConcreteSafetyPath(t *testing.T) {
	in, view, bugs := bug669Inputs(t)
	c := bug669Compute(t, in, view, bugs)
	paths := bug669Paths(t, c)
	if len(paths) != 2 {
		t.Fatalf("want separate checks: %v", paths)
	}
	a, b := bug669Named(t, paths, "BadA"), bug669Named(t, paths, "BadB")
	for i, p := range []map[string]any{a, b} {
		if p["status"] != "path" || p["kind"] != "safety" || p["shortest"] != true || p["caught"] != true {
			t.Fatalf("lost safety qualification: %v", p)
		}
		for _, key := range []string{"trace", "source", "snapshot"} {
			if !reflect.DeepEqual(p[key], bug669Map(t, bugs[i])[key]) {
				t.Fatalf("%s changed from checked evidence", key)
			}
		}
		states, ok := p["states"].([]any)
		if !ok || len(states) != 4 {
			t.Fatalf("path was collapsed or recomputed: %v", p)
		}
		for j, want := range []string{"Ready", "Working", "Working", "Working"} {
			s := states[j].(map[string]any)
			if s["index"] != float64(j+1) || s["label"] != want || s["id"] == "" {
				t.Fatalf("step %d: %v", j+1, s)
			}
		}
		if states[1].(map[string]any)["id"] != states[2].(map[string]any)["id"] || states[2].(map[string]any)["id"] == states[3].(map[string]any)["id"] {
			t.Fatal("reader identity ignored invariant truth or lost repeated labels")
		}
		last := states[3].(map[string]any)
		if last["planted"] != true || last["action_says"] != p["says"] {
			t.Fatal("planted action not labeled with locked words")
		}
	}
	if a["states"].([]any)[3].(map[string]any)["id"] == b["states"].([]any)[3].(map[string]any)["id"] {
		t.Fatal("different violated-rule sets merged")
	}
	if a["rule_says"] != in.Lock.Statements[1].Says || b["rule_says"] != "Every result has its owner." {
		t.Fatal("violated rules lost exact says words")
	}
	if len(c.States) != 3 || c.Report.Counts["tlc_states"] != 5 || len(c.Report.Hidden) != 1 {
		t.Fatal("bug states polluted correct-model chart/counts")
	}
	before := string(bug669JSON(t, c))
	bugs[0]["snapshot"].(map[string]any)["model_sha256"] = "changed"
	if string(bug669JSON(t, c)) != before {
		t.Fatal("result aliases caller evidence")
	}
}
func bug669Temporal(t *testing.T) (statechart.Input, string, []map[string]any) {
	in, view, bugs := bug669Inputs(t)
	for i, name := range []string{"Spin", "Stall"} {
		b := bug669Map(t, bugs[0])
		b["name"] = name
		b["label"] = strings.ToLower(name)
		b["outcome"] = string(tlc.PropertyViolated)
		b["violated"] = "EventuallyDone"
		b["planted"] = []int{3}
		tr := b["trace"].(map[string]any)
		tr["check"] = "known bug " + strings.ToLower(name)
		tr["violated"] = "EventuallyDone"
		tr["states"] = tr["states"].([]any)[:3]
		tr["states"].([]any)[2].(map[string]any)["action"] = name
		if i == 0 {
			tr["loop"] = 2
		} else {
			tr["stutters"] = true
		}
		b["invariants"] = []map[string]bool{{"Safe": true, "Owned": true}, {"Safe": true, "Owned": true}, {"Safe": true, "Owned": true}}
		src := b["source"].(map[string]any)
		src["config"] = tlc.Config{Specification: "Invariant_BuggySpec", Constants: in.Lock.Bounds, Properties: []string{"EventuallyDone"}}
		bugs = append(bugs, b)
	}
	for _, x := range []struct {
		name, outcome, message string
		caught                 bool
	}{{"Miss", "passed", "expected Safe to be violated; TLC found no violation", false}, {"Failed", "error", "TLC failed: operator Broken is undefined", false}, {"Absent", "violated", "", true}} {
		b := bug669Map(t, bugs[0])
		b["name"] = x.name
		b["label"] = strings.ToLower(x.name)
		b["outcome"] = x.outcome
		b["caught"] = x.caught
		b["message"] = x.message
		if !x.caught {
			delete(b, "violated")
			delete(b, "steps")
		}
		delete(b, "trace")
		delete(b, "invariants")
		delete(b, "planted")
		bugs = append(bugs, b)
	}
	// The gate can return a real trace while refusing to call a bug caught:
	// this check expected Owned, but TLC found Safe false and Owned true.
	wrong := bug669Map(t, bugs[0])
	wrong["name"], wrong["label"], wrong["caught"] = "WrongRule", "wrong-rule", false
	wrong["message"] = "expected Owned to be violated; TLC found Safe violated"
	tr := wrong["trace"].(map[string]any)
	tr["check"] = "known bug wrong-rule"
	tr["states"].([]any)[3].(map[string]any)["action"] = "WrongRule"
	bugs = append(bugs, wrong)
	return in, view, bugs
}
func TestKnownBug669TemporalAndDiagnostics(t *testing.T) {
	in, view, bugs := bug669Temporal(t)
	c := bug669Compute(t, in, view, bugs)
	paths := bug669Paths(t, c)
	if len(paths) != 8 {
		t.Fatalf("lost separate checks: %v", paths)
	}
	for _, name := range []string{"Spin", "Stall"} {
		p := bug669Named(t, paths, name)
		if p["status"] != "path" || p["kind"] != "temporal" || p["shortest"] == true {
			t.Fatalf("temporal counterexample became safety: %v", p)
		}
		trace := p["trace"].(map[string]any)
		if name == "Spin" && trace["loop"] != float64(2) || name == "Stall" && trace["stutters"] != true {
			t.Fatal("lost infinite ending")
		}
		if len(p["states"].([]any)) != 3 {
			t.Fatal("temporal occurrences collapsed")
		}
	}
	for _, name := range []string{"Miss", "Failed", "Absent", "WrongRule"} {
		p := bug669Named(t, paths, name)
		if p["status"] != "diagnostic" || p["code"] == nil || p["code"] == "" || p["message"] == nil || p["message"] == "" || p["shortest"] == true {
			t.Fatalf("dishonest failed check: %v", p)
		}
		if ss, ok := p["states"].([]any); ok && len(ss) > 0 {
			t.Fatal("fabricated successful bug path")
		}
	}
	wrong := bug669Named(t, paths, "WrongRule")
	if wrong["message"] != "expected Owned to be violated; TLC found Safe violated" || !reflect.DeepEqual(wrong["trace"], bugs[len(bugs)-1]["trace"]) {
		t.Fatal("uncaught trace lost its actual diagnostic or retained counterexample")
	}
	if !strings.Contains(bug669Named(t, paths, "Failed")["message"].(string), "operator Broken is undefined") {
		t.Fatal("actual failure diagnostic lost")
	}
}
func TestKnownBug669RejectsUnboundTrace(t *testing.T) {
	in, view, bugs := bug669Inputs(t)
	// First require the feature so baseline failure is behavioral, then exercise
	// corrupt inputs. A corrupt check may return a refusal or its own diagnostic,
	// but must not make its neighbor disappear or become a successful path.
	_ = bug669Paths(t, bug669Compute(t, in, view, bugs))
	for _, edit := range []func(map[string]any){
		func(b map[string]any) { b["trace"].(map[string]any)["module"] = "Other" },
		func(b map[string]any) { b["trace"].(map[string]any)["check"] = "known bug other" },
		func(b map[string]any) {
			b["source"].(map[string]any)["config"].(map[string]any)["Constants"].(map[string]any)["Workers"] = "99"
		},
		func(b map[string]any) { b["invariants"] = []any{} },
		func(b map[string]any) {
			b["trace"].(map[string]any)["states"].([]any)[3].(map[string]any)["index"] = 99
		},
	} {
		bad := bug669Map(t, bugs[0])
		edit(bad)
		raw := bug669Map(t, in)
		raw["bugs"] = []any{bad, bugs[1]}
		var input statechart.Input
		if e := json.Unmarshal(bug669JSON(t, raw), &input); e != nil {
			t.Fatal(e)
		}
		c, e := statechart.Compute(t.Context(), input, []byte(view))
		if e != nil {
			if c != nil {
				t.Fatal("partial result on refusal")
			}
			continue
		}
		p := bug669Named(t, bug669Paths(t, c), "BadA")
		if p["status"] != "diagnostic" {
			t.Fatal("unbound trace rendered as checked")
		}
	}
}
func TestKnownBug669SVGAndMarkdownPanels(t *testing.T) {
	in, view, bugs := bug669Temporal(t)
	c := bug669Compute(t, in, view, bugs)
	svg, e := c.SVG()
	if e != nil {
		t.Fatal(e)
	}
	root := svg608Parse(t, svg)
	panels := root.groups("data-bug-path")
	if len(panels) != 4 {
		t.Fatalf("want four separate SVG paths, got %d", len(panels))
	}
	names := map[string]bool{}
	var boxes []svg608Box
	viewBox := strings.Fields(root.attrs["viewBox"])
	if len(viewBox) != 4 {
		t.Fatal("SVG has no complete viewBox")
	}
	width, height := svg608Number(t, viewBox[2]), svg608Number(t, viewBox[3])
	for _, panel := range panels {
		name := panel.attrs["data-bug-path"]
		if names[name] {
			t.Fatal("duplicate path panel")
		}
		names[name] = true
		nodes := panel.groups("data-trace-index")
		want := 4
		if name == "Spin" || name == "Stall" {
			want = 3
		}
		if len(nodes) != want {
			t.Fatalf("%s lost numbered occurrences", name)
		}
		for i, n := range nodes {
			if n.attrs["data-trace-index"] != strconv.Itoa(i+1) {
				t.Fatal("SVG numbering differs from TLC")
			}
			var visible strings.Builder
			for _, tx := range n.all("text") {
				visible.WriteString(tx.text)
			}
			if !strings.Contains(visible.String(), strconv.Itoa(i+1)) || !strings.Contains(visible.String(), []string{"Ready", "Working", "Working", "Working"}[i]) {
				t.Fatalf("number/label only in metadata: %s", visible.String())
			}
			if len(n.all("rect")) == 0 {
				t.Fatal("path node has no visible outline")
			}
			box := svg608Rect(t, n)
			if box.x0 < 0 || box.y0 < 0 || box.x1 > width || box.y1 > height {
				t.Fatal("numbered path node is clipped by the image")
			}
			for _, previous := range boxes {
				if box.x0 < previous.x1 && previous.x0 < box.x1 && box.y0 < previous.y1 && previous.y0 < box.y1 {
					t.Fatal("numbered occurrences overlap instead of remaining legible")
				}
			}
			boxes = append(boxes, box)
		}
		if len(panel.all("path")) < want-1 {
			t.Fatal("path lacks directed transitions")
		}
	}
	var visible strings.Builder
	for _, tx := range root.all("text") {
		visible.WriteString(tx.text)
		visible.WriteByte('\n')
	}
	for _, want := range []string{"Lose <a result> & keep going.", "Every job eventually finishes.", "operator Broken is undefined", "expected Owned to be violated; TLC found Safe violated", "Workers", "Local.tla", "loop", "stutter"} {
		if !strings.Contains(strings.ToLower(visible.String()), strings.ToLower(want)) {
			t.Fatalf("SVG visible report lost %q", want)
		}
	}
	for _, md := range []string{c.Markdown(), c.CompactMarkdown()} {
		decoded := html.UnescapeString(md)
		if strings.Count(md, "```mermaid") < 5 {
			t.Fatal("known bugs lack separate complete Mermaid panels")
		}
		for _, want := range []string{"bad-a", "bad-b", "spin", "stall", "Lose <a result> & keep going.", "Every job eventually finishes.", "operator Broken is undefined", "expected Owned to be violated; TLC found Safe violated", "Workers", "Local.tla", "loop", "stutter", "shortest"} {
			if !strings.Contains(strings.ToLower(decoded), strings.ToLower(want)) {
				t.Fatalf("Markdown lost %q", want)
			}
		}
	}
}

