		if b.name == "Failed" {
			model = strings.Replace(model, "====", "Failed == BadA\n====", 1)
			f.Files[f.Manifest.Module] = []byte(model)
		}
		f.Lock.Statements = append(f.Lock.Statements, project.Statement{Name: b.name, Kind: project.Bug, Expect: b.rule, Says: b.says, CodeBehavior: "hypothetical"})
	}
	for i := range f.Lock.Statements {
		s := &f.Lock.Statements[i]
