		if e != nil {
			t.Fatal(e)
		}
	}
	g := tlc.GraphResult{Module: "Dashboard631", Config: tlc.Config{Specification: "Spec", Constants: f.Lock.Bounds, Invariants: []string{"Safe"}}, Tool: tlc.GraphTool{Image: f.Report.Toolchain.JavaImage, JarSHA256: f.Report.Toolchain.TLCJarSHA256}, Run: tlc.Result{Outcome: tlc.Passed, Version: f.Report.Toolchain.TLC, Depth: 3, DistinctStates: 3, StatesGenerated: 7}, StateCount: 3, StepCount: 6}
	g.Graph.Initial = []string{"0"}
	truth := map[string]map[string]bool{}
	for i, id := range []string{"0", "1", "2"} {
		g.Graph.States = append(g.Graph.States, tlc.GraphState{ID: id, Label: "n = " + id, Values: map[string]string{"n": id}})
		action := "Advance"
		if i == 2 {
			action = "Reset"
		}
		g.Graph.Steps = append(g.Graph.Steps, tlc.GraphStep{From: id, To: []string{"1", "2", "0"}[i], Action: action}, tlc.GraphStep{From: id, To: id, Action: "Poll"})
		truth[id] = map[string]bool{"Safe": true}
	}
	in := statechart.Input{Graph: g, Lock: f.Lock, Invariants: truth}
	var raw map[string]any
