	for _, name := range []string{"BadA", "BadB", "Spin", "Stall", "Failed"} {
		label := map[string]string{"BadA": "bad-a", "BadB": "bad-b", "Spin": "spin", "Stall": "stall", "Failed": "failed"}[name]
		expect, outcome := "Safe", string(tlc.Violated)
		source := statechart.Source{Module: g.Module, Config: tlc.Config{Specification: "Invariant_BuggySpec", Constants: f.Lock.Bounds, Invariants: []string{"Safe"}}, Tool: g.Tool, TLC: g.Run.Version}
		final := "3"
		if name == "BadB" {
			final = "4"
		}
		if name == "Spin" {
			final = "0"
		}
		if name == "Stall" {
			final = "1"
		}
		trace := tlc.TraceFile{Module: g.Module, Check: "known bug " + label, Violated: "Safe", TLC: g.Run.Version, States: []tlc.TraceState{{Index: 1, Action: "Initial predicate", TLA: map[string]string{"n": "0"}}, {Index: 2, Action: "Advance", TLA: map[string]string{"n": "1"}}, {Index: 3, Action: name, TLA: map[string]string{"n": final}}}}
		if name == "Spin" || name == "Stall" {
			expect = "Live"
			outcome = string(tlc.PropertyViolated)
			trace.Violated = expect
			source.Config.Invariants = nil
			source.Config.Properties = []string{"Live"}
			if name == "Spin" {
				trace.Loop = 2
			} else {
				trace.Stutters = true
			}
		}
		check := map[string]any{"name": name, "label": label, "caught": true, "outcome": outcome, "violated": expect, "trace": trace, "source": source, "snapshot": snapshot, "invariants": []map[string]bool{{"Safe": true}, {"Safe": true}, {"Safe": expect == "Live"}}, "planted": []int{3}}
		var st project.Statement
		for _, s := range f.Lock.Statements {
			if s.Name == name {
				st = s
			}
		}
		bug := map[string]any{"name": name, "label": label, "says": st.Says, "expect": expect, "caught": true, "outcome": outcome, "violated": expect, "steps": 2, "counterexample": trace, "code_behavior": "hypothetical"}
		if name == "Failed" {
			for _, m := range []map[string]any{check, bug} {
				m["caught"] = false
				m["outcome"] = "error"
				m["message"] = "TLC failed: operator Broken is undefined"
				delete(m, "trace")
				delete(m, "counterexample")
				delete(m, "invariants")
				delete(m, "planted")
			}
			f.Report.Passed = false
