		t.Fatalf("reader endpoints: SVG %d page %d", svg.Code, page.Code)
	}
	if strings.Count(svg.Body.String(), `data-bug-path=`) != 4 {
		t.Fatal("dashboard SVG discarded separate numbered bug paths")
	}
	body := html.UnescapeString(page.Body.String())
	if strings.Count(body, `data-bug-path=`) < 4 {
		t.Fatal("dashboard page hides bug paths in a JSON record or poster link")
	}
	for _, want := range []string{"BadA", "BadB", "Spin", "Stall", "Cross the limit <now> & lose safety.", "Every cycle eventually finishes.", "operator Broken is undefined", "Limit", "loop", "stutter"} {
		if !strings.Contains(strings.ToLower(body), strings.ToLower(want)) {
			t.Fatalf("dashboard page lost %q", want)
		}
	}
	if strings.Contains(strings.ToLower(body), "<script") {
		t.Fatal("reader page requires executable script")
	}
	return svg.Body.String(), page.Body.String()
}
func TestKnownBug669ReceiptDashboardAndOfflineRecovery(t *testing.T) {
	f := dashboard669Fixture(t)
