	if e := receipt.Write(archive, f.Report); e != nil {
		t.Fatal(e)
	}
	if !reflect.DeepEqual(before, reader631JSON(t, f.Report)) {
		t.Fatal("receipt rendering mutated evidence")
	}
	for _, name := range []string{"receipt.json", "reader.json", "reader.svg", "receipt.md"} {
		data, e := os.ReadFile(filepath.Join(archive, name))
		if e != nil {
			t.Fatal(e)
		}
		for _, want := range []string{"BadA", "BadB", "Spin", "Stall", "operator Broken is undefined"} {
			if !strings.Contains(string(data), want) {
				t.Fatalf("%s lost bug evidence %s", name, want)
			}
		}
	}
	var restored verify.Report
	data, e := os.ReadFile(filepath.Join(archive, "receipt.json"))
	if e != nil {
		t.Fatal(e)
	}
	if e = json.Unmarshal(data, &restored); e != nil {
		t.Fatal(e)
	}
	if !reflect.DeepEqual(reader631JSON(t, restored.Reader), reader631JSON(t, f.Report.Reader)) {
		t.Fatal("structured receipt lost reader evidence")
	}
	r := reader631Repo(t, "owner/bugs", strings.Repeat("6", 40), 669, []reader631Fixture{f}, reader631Archive(t, []reader631Fixture{f}, nil))
	s := &Server{Repos: []*Repo{r}, Cache: t.TempDir()}
	p := reader631Find(t, reader631Load(t, s, r), r.Name, f.Dir)
	if p.Status != "chart" {
