	cold := &Server{Cache: s.Cache, Repos: []*Repo{{Name: r.Name}}}
	cold.loadSnapshot()
	svg2, page2 := dashboard669Visible(t, cold, p)
	if svg2 != svg || page2 != page {
		t.Fatal("offline restart changed numbered paths, diagnostics or provenance")
	}
}

