package verify_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/tlc"
	"github.com/gitdek/invariant/internal/toolchain"
	"github.com/gitdek/invariant/internal/verify"
)

func TestKnownBug669RetainsTemporalTraceWithoutOutputDirectory(t *testing.T) {
	f := tlc497Setup(t)
	r, e := verify.RunModel(tlc497Context(t), tlc497Project(t), f.tc)
	if e != nil || r == nil {
		t.Fatalf("model gate: %v", e)
	}
	var got struct {
		Bugs []struct {
			Name           string
			Caught         bool
			Counterexample *tlc.TraceFile `json:"counterexample"`
		}
	}
	data, _ := json.Marshal(r)
	if e = json.Unmarshal(data, &got); e != nil {
		t.Fatal(e)
	}
	found := false
	for _, b := range got.Bugs {
		if b.Name == "B2" {
			found = true
			if !b.Caught || b.Counterexample == nil || !b.Counterexample.Stutters || b.Counterexample.Loop != 0 || len(b.Counterexample.States) != 1 {
				t.Fatalf("model-only temporal evidence lost: %+v", b)
			}
		}
	}
	if !found {
		t.Fatal("property bug missing")
	}
}

// The builder extends statechart_integration_test.go in package verify_test,
// under //go:build integration, with TestKnownBug669PinnedTLCIntegration calling
// knownBug669Real(t). Existing CI integration shards run it; missing Docker or
// pinned TLC must fail that lane, never skip. No acceptance check downloads tools.
// This checks the real breadth-first choice in a graph with a longer alternative,
// invariant evaluation outside the correct graph, temporal loop/stutter endings,
// formalization, publication input, receipt output and saved-result validation.
const knownBug669Model = `---- MODULE KnownBug669 ----
EXTENDS Naturals
VARIABLE n
vars == <<n>>
Init == n = 0
Fast == n = 0 /\ n' = 1
Slow == n = 0 /\ n' = 2
Later == n = 2 /\ n' = 3
Join == n = 3 /\ n' = 1
Done == n = 1 /\ UNCHANGED n
Around == n = 6 /\ n' = 7
Back == n = 7 /\ n' = 6
Next == Fast \/ Slow \/ Later \/ Join \/ Done \/ Around \/ Back
Spec == Init /\ [][Next]_vars
Fair == WF_vars(Next)
Safe == n < 4
Owned == n # 5
Live == []<>(n = 1)
BadA == n = 1 /\ n' = 4
BadB == n = 1 /\ n' = 5
Spin == n = 1 /\ n' = 6
Stall == n = 0 /\ n' = 8
====
`

func knownBug669Real(t *testing.T) {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Minute)
	defer cancel()
	tc, e := toolchain.Ensure(ctx)
	if e != nil {
		t.Fatal(e)
	}
	ws := t.TempDir()
	ss := []project.Statement{{Name: "Spec", Kind: project.Spec, Says: "Move to work by either route."}, {Name: "Fair", Kind: project.Fairness, Says: "Enabled work eventually runs."}, {Name: "Safe", Kind: project.Invariant, Says: "The count stays below four."}, {Name: "Owned", Kind: project.Invariant, Says: "The count is never five."}, {Name: "Live", Kind: project.Property, Says: "Work recurs forever."}}
	for _, b := range []struct{ name, expect, says string }{{"BadA", "Safe", "Break safety after work."}, {"BadB", "Owned", "Lose the owner after work."}, {"Spin", "Live", "Loop without returning to work."}, {"Stall", "Live", "Stutter without reaching work."}} {
		ss = append(ss, project.Statement{Name: b.name, Kind: project.Bug, Says: b.says, Expect: b.expect, CodeBehavior: "hypothetical"})
	}
	// BadB's check must find its expected first violated invariant; use the same
	// expected Safe while retaining both false rules in its reader partition.
	ss[6].Expect = "Safe"
	draft := map[string]any{"name": "Known bug paths", "slug": "known-bug-paths", "module": "KnownBug669", "package": "knownbug", "bounds": map[string]string{}, "statements": ss}
	view := `{"version":1,"state":[{"id":"initial","when":{"eq":[{"var":"n"},"0"]},"label":"Ready"},{"id":"work","when":true,"label":"Working"}],"step":[{"id":"all","when":true,"label":"Continue"}]}`
	data, _ := json.Marshal(draft)
	for name, body := range map[string]string{"proposal.json": string(data), "KnownBug669.tla": knownBug669Model, "view.json": view} {
		if e = os.WriteFile(filepath.Join(ws, name), []byte(body), 0600); e != nil {
			t.Fatal(e)
		}
	}
	p, r, e := formalize.Check(ctx, ws, tc)
	if e != nil || p == nil || r == nil || !r.Passed {
		t.Fatalf("real draft: %v, report %+v", e, r)
	}
	if e = p.ValidateReader(); e != nil {
		t.Fatal(e)
	}
	var paths struct {
		Report struct {
			Paths []struct {
				Name, Kind, Status string
				Shortest           bool
				Trace              tlc.TraceFile
				States             []struct {
					Index     int
					Label, ID string
					Violated  []string `json:"violated_rules"`
				}
			} `json:"bug_paths"`
		}
	}
	data, _ = json.Marshal(p.Reader.Chart)
	if e = json.Unmarshal(data, &paths); e != nil {
		t.Fatal(e)
	}
	if len(paths.Report.Paths) != 4 {
		t.Fatalf("proposal lost known bugs: %s", data)
	}
	for _, b := range paths.Report.Paths {
		if b.Status != "path" {
			t.Fatalf("real counterexample not drawn: %+v", b)
		}
		switch b.Name {
		case "BadA", "BadB":
			if b.Kind != "safety" || !b.Shortest || len(b.States) != 3 || b.Trace.States[1].TLA["n"] != "1" {
				t.Fatalf("did not retain TLC's shortest route: %+v", b)
			}
			if b.States[1].Label != "Working" || b.States[2].Label != "Working" || b.States[1].ID == b.States[2].ID {
				t.Fatal("violating state disappeared")
			}
			if b.Name == "BadB" && len(b.States[2].Violated) != 2 {
				t.Fatal("did not evaluate every rule at violating state")
			}
		case "Spin":
			if b.Kind != "temporal" || b.Shortest || b.Trace.Loop == 0 || b.Trace.Stutters {
				t.Fatal("loop became finite failure")
			}
		case "Stall":
			if b.Kind != "temporal" || b.Shortest || !b.Trace.Stutters || b.Trace.Loop != 0 {
				t.Fatal("stuttering ending lost")
			}
		}
	}
	receiptDir := t.TempDir()
	if e = receipt.Write(receiptDir, r); e != nil {
		t.Fatal(e)
	}
	for _, name := range []string{"receipt.json", "reader.json", "reader.svg", "receipt.md"} {
		b, e := os.ReadFile(filepath.Join(receiptDir, name))
		if e != nil {
			t.Fatal(e)
		}
		for _, want := range []string{"BadA", "BadB", "Spin", "Stall"} {
			if !strings.Contains(string(b), want) {
				t.Fatalf("%s lost %s", name, want)
			}
		}
	}
	var restored formalize.Proposal
	data, _ = json.Marshal(p)
	if e = json.Unmarshal(data, &restored); e != nil {
		t.Fatal(e)
	}
	if e = restored.ValidateReader(); e != nil {
		t.Fatal(e)
	}
	if restored.Reader.Chart.Markdown() != p.Reader.Chart.Markdown() {
		t.Fatal("saved proposal changed paths")
	}
}

