package replaytest

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/tlc"
	"github.com/gitdek/invariant/internal/verify"
)

// Bug.counterexample is an optional *tlc.TraceFile retained even without an
// outDir. The existing Bug.Trace filename and caught/verdict semantics remain.
// This additional explanatory data is excluded from verify.Fingerprint, and
// bound instead by reader/saved-evidence identities. It survives EvidenceJSON
// and receipt.Write. Existing code-replay evidence remains independent.
func retained669(t *testing.T, r *verify.Report) []tlc.TraceFile {
	t.Helper()
	data, e := json.Marshal(r)
	if e != nil {
		t.Fatal(e)
	}
	var got struct {
		Bugs []struct {
			Counterexample *tlc.TraceFile `json:"counterexample"`
		} `json:"bugs"`
	}
	if e = json.Unmarshal(data, &got); e != nil {
		t.Fatal(e)
	}
	var traces []tlc.TraceFile
	for i, b := range got.Bugs {
		if b.Counterexample == nil {
			t.Fatalf("bug %d lost its in-memory counterexample without outDir", i)
		}
		traces = append(traces, *b.Counterexample)
	}
	return traces
}
func TestKnownBug669RetainsModelAndOrdinaryCounterexamples(t *testing.T) {
	dir, tc, _ := gateFixture857(t, "go", []string{"hypothetical", "hypothetical"}, false)
	model := run857(t, dir, tc, true)
	traces := retained669(t, model)
	if len(traces) != 2 || !model.Passed {
		t.Fatalf("changed known-bug verdict: %+v", model)
	}
	for i, tr := range traces {
		if len(tr.States) != 4 || tr.States[3].TLA["n"] != []string{"3", "4"}[i] || tr.Check != "known bug "+model.Bugs[i].Label || tr.Violated != "Safe" || tr.Module != "BugGate" {
			t.Fatalf("wrong original trace: %+v", tr)
		}
	}
	ordinary, e := verify.Run(t.Context(), dir, t.TempDir(), tc)
	if e != nil {
		t.Fatal(e)
	}
	if !reflect.DeepEqual(retained669(t, ordinary), traces) || !ordinary.Passed {
		t.Fatal("ordinary/model-only paths or verdicts differ")
	}
	fp := verify.Fingerprint(*ordinary)
	data, e := json.Marshal(ordinary)
	if e != nil {
		t.Fatal(e)
	}
	var wire map[string]any
	_ = json.Unmarshal(data, &wire)
	for _, b := range wire["bugs"].([]any) {
		delete(b.(map[string]any), "counterexample")
	}
	data, _ = json.Marshal(wire)
	var without verify.Report
	_ = json.Unmarshal(data, &without)
	if verify.Fingerprint(without) != fp {
		t.Fatal("explanation changed verification fingerprint")
	}
	archive := t.TempDir()
	if e = receipt.Write(archive, ordinary); e != nil {
		t.Fatal(e)
	}
	data, e = os.ReadFile(filepath.Join(archive, "receipt.json"))
	if e != nil {
		t.Fatal(e)
	}
	var restored verify.Report
	if e = json.Unmarshal(data, &restored); e != nil {
		t.Fatal(e)
	}
	if !reflect.DeepEqual(retained669(t, &restored), traces) {
		t.Fatal("receipt archive discarded trace provenance")
	}
}
